import { t11, type L11 } from '../math'
import type { ThemeItem, ThemeTier } from '../theme'
import type { ThemeMode } from '../../lib/quiz/themeModes'
import { BANDS, BITS, CONSTS, TOOLS } from './extraRows'

function n(
  ru: string,
  en: string,
  de: string,
  zh: string,
  es: string,
  hi: string,
  ar: string,
  bn: string,
  pt: string,
  ja: string,
  he: string,
): L11 {
  return t11(ru, en, de, zh, es, hi, ar, bn, pt, ja, he)
}

function same(text: string): L11 {
  return n(text, text, text, text, text, text, text, text, text, text, text)
}

function link(
  id: string,
  forward: ThemeMode,
  back: ThemeMode,
  tier: ThemeTier,
  left: L11,
  right: L11,
  leftKey: string,
  rightKey: string,
  note: L11,
): ThemeItem[] {
  return [
    { id: `${id}f`, mode: forward, tier, prompt: left, answer: right, key: rightKey, note },
    { id: `${id}b`, mode: back, tier, prompt: right, answer: left, key: leftKey, note },
  ]
}

export function physicsGeneratedRows(): ThemeItem[] {
  return [
    ...UNITS.flat(),
    ...LETTERS.flat(),
    ...LAWS.flat(),
    ...NAMES.flat(),
    ...CONSTS.flat(),
    ...TOOLS.flat(),
    ...BITS.flat(),
    ...BANDS.flat(),
  ]
}

